head.script:
scwin.params = new Array();
scwin.vCurDate = $c.ut.cGetToday("yyyymmdd");

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        $c.cm.PanelToGroupBox(panel_Top);
        getId = $c.frame.path("../").fn_getId;
        scwin.params = getId();

        // alert("11111=="+cGetDifTodayInputday('20160101','20160102'));

        if (scwin.params[2] === '2') {
            // 코스닥이면
            let strANULFEE_EXMPT_YN = "Y^Y,E^Y(일부면제),N^N";
            cmb_ANULFEE_EXMPT_YN.CBData = strANULFEE_EXMPT_YN;
        } else {
            let strANULFEE_EXMPT_YN = "Y^Y,N^N";
            cmb_ANULFEE_EXMPT_YN.CBData = strANULFEE_EXMPT_YN;
        }
        await scwin.read();

        // 코스닥이면서 외국주권일 경우, 환율를 입력할 수 있다. 20100106  - params[2] == "2"
        // (3393)유가도 환율정보를 입력할 수 있도록 함.2011.03
        if (dts_yearAssessmentFee.getCellData(1, "SECUGRP_ID") === "FS") {
            panel_APPL_EXCHRT.show("");
        } else {
            panel_APPL_EXCHRT.hide();
        }
        const basYear = 2014;
        if (parseInt(scwin.params[1]) >= basYear && scwin.params[2] === '2') {
            txb_CAP.hide();
            lbl_CAP.hide();
            txb_AVG_MKTCAP.show("");
            lbl_AVG_MKTCAP.show("");
        } else {
            txb_CAP.show("");
            lbl_CAP.show("");
            txb_AVG_MKTCAP.hide();
            lbl_AVG_MKTCAP.hide();
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF40801.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name trs_Update_OnSuccess
 * @description Update On Success 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_Update_OnSuccess = async function() {
    try {
        await $c.win.alert($c.stf.getMessageParam("MSG-A001", "연부과금 수정"));
        await $c.win.closePopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF40801.trs_Update_OnSuccess" });
    }
};

/**
 * @method
 * @name trs_Update_OnFail
 * @description Update On Fail 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_Update_OnFail = async function() {
    try {
        await $c.win.alert($c.stf.getMessageParam("MSG-A002", "연부과금 수정"));
        // alert(trs_Update.ErrorMsg);
        // alert(dts_C_All.ErrorMsg);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF40801.trs_Update_OnFail" });
    }
};

/**
 * @method
 * @name btn_search_onclick
 * @description 「search」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_search_onclick = function() {
    try {
        $c.lc.fn_PopFindZipCd();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF40801.btn_search_onclick" });
    }
};

/**
 * @method
 * @name btn_modify_onclick
 * @description 「수정」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_modify_onclick = async function() {
    try {
        await scwin.update();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF40801.btn_modify_onclick" });
    }
};

/**
 * @method
 * @name btn_close_onclick
 * @description btn_close 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_close_onclick = async function() {
    try {
        await $c.win.closePopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF40801.btn_close_onclick" });
    }
};

/**
 * @method
 * @name dts_yearAssessmentFee_OnLoadCompleted
 * @description dts_yearAssessmentFee 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_yearAssessmentFee_OnLoadCompleted = function(rowcount) {
    try {
        if (dts_yearAssessmentFee.getCellData(1, "ANULFEE_FINAL_YN") === "Y") {
            panel_update.hide();
        } else {
            panel_update.show("");
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF40801.dts_yearAssessmentFee_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name dts_yearAssessmentFee_OnLoadError
 * @description dts_yearAssessmentFee 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_yearAssessmentFee_OnLoadError = async function() {
    try {
        await $c.win.alert(dts_yearAssessmentFee);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF40801.dts_yearAssessmentFee_OnLoadError" });
    }
};

/**
 * @method
 * @name img_ANULFEE_EXMPT_STRT_DD_onclick
 * @description img_ANULFEE_EXMPT_STRT_DD 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.img_ANULFEE_EXMPT_STRT_DD_onclick = function() {
    try {
        popUpCalendar2(edt_ANULFEE_EXMPT_STRT_DD);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF40801.img_ANULFEE_EXMPT_STRT_DD_onclick" });
    }
};

/**
 * @method
 * @name img_ANULFEE_EXMPT_END_DD_onclick
 * @description img_ANULFEE_EXMPT_END_DD 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.img_ANULFEE_EXMPT_END_DD_onclick = function() {
    try {
        popUpCalendar2(edt_ANULFEE_EXMPT_END_DD);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF40801.img_ANULFEE_EXMPT_END_DD_onclick" });
    }
};

/**
 * @method
 * @name cmb_ANULFEE_EXMPT_YN_onselchange
 * @description cmb_ANULFEE_EXMPT_YN onselchange 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.cmb_ANULFEE_EXMPT_YN_onselchange = function() {
    try {
        if (cmb_ANULFEE_EXMPT_YN.BindColVal === "E") {
            //     "일부면제" 이면
            panel_EXMPT.show("");

            /*	기본값 201X0101~ 201X1231 	*/
            edt_ANULFEE_EXMPT_STRT_DD.setValue((parseInt(scwin.vCurDate.substring(0, 4), 10) - 1) + "0101");
            edt_ANULFEE_EXMPT_END_DD.setValue((parseInt(scwin.vCurDate.substring(0, 4), 10) - 1) + "1231");
        } else {
            panel_EXMPT.hide();
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF40801.cmb_ANULFEE_EXMPT_YN_onselchange" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name read
 * @description 오늘날짜
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.read = async function() {
    url += "&SCREN_ID=" + "ULDSTF40801.xml" + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    url += "&ISUR_CD=" + scwin.params[0];
    url += "&BAS_YY=" + scwin.params[1];
    url += "&MKT_ID=" + scwin.params[2];
    url += "&ANULFEE_NOTI_IMPOST_NO=" + scwin.params[3];
    const sbmOptions = {
        id : "sbm_dts_yearAssessmentFee",
        action : "/YearAssessmentFeeManagement.do",
        ref : "",
        target : "dts_yearAssessmentFee=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    if (cmb_ANULFEE_EXMPT_YN.BindColVal === "E") {
        panel_EXMPT.show("");
    } else {
        panel_EXMPT.hide();
    }
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name update
 * @description update 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.update = async function() {
    if (cmb_ANULFEE_EXMPT_YN.BindColVal === "N") {
        if (txb_ANULFEE_EXMPT_RSN_DSC.getValue() !== "") {
            await $c.win.alert("[면제여부]가 'N'일경우 입력하실 수 없습니다.");
            txb_ANULFEE_EXMPT_RSN_DSC.setValue("");
            return;
        }
    }
    if (!$c.stf.checkMaxLength(txb_ANULFEE_EXMPT_RSN_DSC, 200, "면제사유")) {
        txb_ANULFEE_EXMPT_RSN_DSC.setValue("");
        txb_ANULFEE_EXMPT_RSN_DSC.focus();
        return false;
    }
    if (cmb_ANULFEE_EXMPT_YN.BindColVal !== "E") {
        edt_ANULFEE_EXMPT_STRT_DD.setValue("");
        edt_ANULFEE_EXMPT_END_DD.setValue("");
    } else {
        if ($c.ut.cIsNull(edt_ANULFEE_EXMPT_STRT_DD)) {
            await $c.win.alert("면제기간 시작일자를 입력해 주세요.");
            edt_ANULFEE_EXMPT_STRT_DD.focus();
            return false;
        }
        if ($c.ut.cIsNull(edt_ANULFEE_EXMPT_END_DD)) {
            await $c.win.alert("면제기간 종료일자를 입력해 주세요.");
            edt_ANULFEE_EXMPT_END_DD.focus();
            return false;
        }
        if (edt_ANULFEE_EXMPT_STRT_DD.getValue() > edt_ANULFEE_EXMPT_END_DD.getValue()) {
            await $c.win.alert("면제기간 종료일자는 면제기간시작일자보다 커야합니다.");
            edt_ANULFEE_EXMPT_STRT_DD.focus();
            return false;
        }
    }
    const rtn = confirm('내용을 수정 하시겠습니까?');
    if (rtn === 1) // [확인] 버튼이 눌려졌을 경우

    {
        let url = "/YearAssessmentFeeManagement.do?SCREN_ID=" + "ULDSTF40801.xml" + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_03 + "&method=updateYearAssessmentFee";
        url += "&ISUR_CD=" + scwin.params[0];
        url += "&BAS_YY=" + scwin.params[1];
        url += "&MKT_ID=" + scwin.params[2];
        url += "&ANULFEE_NOTI_IMPOST_NO=" + scwin.params[3];
        url += "&ANULFEE_EXMPT_YN=" + cmb_ANULFEE_EXMPT_YN.BindColVal;
        cmb_ANULFEE_EXMPT_YN;
        trs_Update.Action = encodeURI(url);
        trs_Update.KeyValue = "JSP(I:pInput=dts_yearAssessmentFee)";
        trs_Update.Post();
    }
};

/**
 * @method
 * @name getPar
 * @description 넘길 인수를 지정하는 펑션
 * @param {Array} arrPar 팝업 파라미터 배열(참조 채움)
 * @returns {void}
 * @hidden N
 */
scwin.getPar = function(arrPar) {
    // 넘길 인수를 지정하는 펑션
    arrPar[0] = ""; // 코드값을 포함할 컨트롤
    arrPar[1] = ""; // 명칭값을 포함할 컨트롤
    arrPar[2] = ""; // 명칭값을 포함할 컨트롤
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    //
    // ********************************************************************
    arrPar, length;
};

/**
 * @method
 * @name setPar
 * @description set Par 처리
 * @param {Array} arrPar 팝업 파라미터 배열(참조 채움)
 * @returns {void}
 * @hidden N
 */
scwin.setPar = function(arrPar) {
    txb_ZIPCD.setValue(arrPar[0]);
    txb_ADDR.setValue(arrPar[1]);
};
